// src/components/IDEPage.jsx
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Editor from '@monaco-editor/react';
import { Terminal } from 'xterm';
import 'xterm/css/xterm.css';
import '../css/IDEPage.css';

export default function IDEPage() {
    const navigate = useNavigate();
    const [files, setFiles] = useState([
        { name: 'main.c', content: '#include <stdio.h>\nint main(void) {\n    printf("Hello World\n");\n    return 0;\n}' },
        { name: 'generated-icon.png', content: '' }
    ]);
    const [activeIndex, setActiveIndex] = useState(0);
    const termRef = useRef(null);
    const xtermRef = useRef(null);

    useEffect(() => {
        xtermRef.current = new Terminal({ convertEol: true });
        xtermRef.current.open(termRef.current);
        xtermRef.current.writeln('The system is starting up...');
    }, []);

    const handleFileClick = idx => setActiveIndex(idx);
    const handleEditorChange = (value) => {
        setFiles(files.map((f, i) => i === activeIndex ? { ...f, content: value } : f));
    };

    return (
        <div className="ide-container">
            <header className="ide-header">
                <button className="ide-back-btn" onClick={() => navigate(-1)}>&larr; 뒤로</button>
                <h2>IDE</h2>
            </header>

            <div className="ide-body">
                <aside className="file-tree">
                    {files.map((file, idx) => (
                        <div
                            key={file.name}
                            className={`file-item ${idx === activeIndex ? 'active' : ''}`}
                            onClick={() => handleFileClick(idx)}
                        >
                            {file.name}
                        </div>
                    ))}
                </aside>

                <div className="editor-pane">
                    <Editor
                        height="100%"
                        defaultLanguage={files[activeIndex].name.endsWith('.c') ? 'c' : 'plaintext'}
                        value={files[activeIndex].content}
                        onChange={handleEditorChange}
                        theme="vs-dark"
                    />

                    <div className="console-container" ref={termRef}></div>
                </div>
            </div>
        </div>
    );
}
